use tauri_plugin_sql::{Migration, MigrationKind};

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
  tauri::Builder::default()

    .plugin(
      tauri_plugin_sql::Builder::default()
        .add_migrations(
          "sqlite:database.db",
          vec![
            Migration {
              version: 1,
              description: "create_full_database_schema",
              sql: r#"
                  PRAGMA foreign_keys = ON;

                  -- =========================================================
                  -- Images
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS images (
                      image_id TEXT PRIMARY KEY,
                      file_path TEXT NOT NULL,
                      width INTEGER NOT NULL CHECK(width > 0),
                      height INTEGER NOT NULL CHECK(height > 0),
                      scale_value REAL NOT NULL CHECK(scale_value > 0)
                  );

                  -- =========================================================
                  -- SegmentationModels
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS segmentation_models (
                      model_id TEXT PRIMARY KEY,
                      model_name TEXT NOT NULL,
                      model_type TEXT NOT NULL CHECK(
                          model_type IN ('neural_network', 'classical')
                      ),
                      model_path TEXT NOT NULL
                  );

                  -- =========================================================
                  -- ProcessingParameters
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS processing_parameters (
                      params_id TEXT PRIMARY KEY,

                      -- JSON строки
                      preprocessing_params TEXT NOT NULL,
                      segmentation_params TEXT NOT NULL,
                      separation_params TEXT NOT NULL
                  );

                  -- =========================================================
                  -- AnalysisRuns
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS analysis_runs (
                      run_id TEXT PRIMARY KEY,

                      image_id TEXT NOT NULL,
                      model_id TEXT NOT NULL,
                      params_id TEXT NOT NULL,

                      created_at INTEGER NOT NULL,

                      FOREIGN KEY(image_id)
                          REFERENCES images(image_id),

                      FOREIGN KEY(model_id)
                          REFERENCES segmentation_models(model_id),

                      FOREIGN KEY(params_id)
                          REFERENCES processing_parameters(params_id)
                  );

                  -- =========================================================
                  -- Masks
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS masks (
                      mask_id TEXT PRIMARY KEY,

                      run_id TEXT NOT NULL,

                      mask_type TEXT NOT NULL CHECK(
                          mask_type IN ('raw', 'cleaned')
                      ),

                      file_path TEXT NOT NULL,

                      FOREIGN KEY(run_id)
                          REFERENCES analysis_runs(run_id)
                  );

                  -- =========================================================
                  -- Objects
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS objects (
                      object_id TEXT PRIMARY KEY,

                      run_id TEXT NOT NULL,
                      mask_id TEXT NOT NULL,

                      object_type TEXT NOT NULL CHECK(
                          object_type IN ('candidate', 'autonomous')
                      ),

                      processing_status TEXT NOT NULL CHECK(
                          processing_status IN ('classified', 'processed')
                      ),

                      FOREIGN KEY(run_id)
                          REFERENCES analysis_runs(run_id),

                      FOREIGN KEY(mask_id)
                          REFERENCES masks(mask_id)
                  );

                  -- =========================================================
                  -- Pores
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS pores (
                      pore_id TEXT PRIMARY KEY,

                      run_id TEXT NOT NULL,

                      source_object_id TEXT NOT NULL,

                      parent_object_id TEXT,

                      pore_type TEXT NOT NULL CHECK(
                          pore_type IN (
                              'autonomous',
                              'separated',
                              'not_separated'
                          )
                      ),

                      centroid_x REAL NOT NULL CHECK(centroid_x >= 0),
                      centroid_y REAL NOT NULL CHECK(centroid_y >= 0),

                      area REAL NOT NULL CHECK(area > 0),

                      diameter REAL NOT NULL CHECK(diameter > 0),

                      FOREIGN KEY(run_id)
                          REFERENCES analysis_runs(run_id),

                      FOREIGN KEY(source_object_id)
                          REFERENCES objects(object_id),

                      FOREIGN KEY(parent_object_id)
                          REFERENCES objects(object_id)
                  );

                  -- =========================================================
                  -- AnalysisResults
                  -- =========================================================

                  CREATE TABLE IF NOT EXISTS analysis_results (
                      result_id TEXT PRIMARY KEY,

                      run_id TEXT NOT NULL,

                      pore_count INTEGER NOT NULL CHECK(pore_count >= 0),

                      porosity REAL NOT NULL CHECK(
                          porosity >= 0
                          AND porosity <= 1
                      ),

                      -- JSON
                      size_distribution TEXT NOT NULL,

                      FOREIGN KEY(run_id)
                          REFERENCES analysis_runs(run_id)
                  );

                  CREATE TABLE IF NOT EXISTS tools (
                  id TEXT PRIMARY KEY,
                  name TEXT NOT NULL,
                  material TEXT NOT NULL,
                  architecture TEXT NOT NULL,
                  image TEXT NOT NULL,
                  removable INTEGER NOT NULL,
                  created_at INTEGER NOT NULL
                  );
                  INSERT OR IGNORE INTO tools (
                    id,
                    name,
                    material,
                    architecture,
                    image,
                    removable,
                    created_at
                  )
                  VALUES (
                    'tool-1',
                    'Segment Tool',
                    'Любой',
                    'threshold',
                    'data:image/jpeg;base64,',
                    0,
                    strftime('%s', 'now')
                  );
              "#,
              kind: MigrationKind::Up,
            }
          ],
        )
        .build(),
    )

    .setup(|app| {
      if cfg!(debug_assertions) {
        app.handle().plugin(
          tauri_plugin_log::Builder::default()
            .level(log::LevelFilter::Info)
            .build(),
        )?;
      }

      Ok(())
    })

    .run(tauri::generate_context!())
    .expect("error while running tauri application");
}